schema_ddl:
CREATE TABLE clienti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    cognome TEXT NOT NULL,
    data_nascita DATE NOT NULL,
    codice_fiscale TEXT NOT NULL UNIQUE,
    cliente_genitore_id INT REFERENCES clienti(id)
);

CREATE TABLE polizze (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    tipo_polizza TEXT NOT NULL,
    premio NUMERIC(10,2) NOT NULL CHECK (premio >= 0),
    data_inizio DATE NOT NULL,
    data_fine DATE CHECK (data_fine IS NULL OR data_fine > data_inizio)
);

CREATE INDEX idx_polizze_cliente_id ON polizze(cliente_id);

CREATE INDEX idx_clienti_cliente_genitore_id ON clienti(cliente_genitore_id);
